import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import fs from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: parse tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this verifies JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.tenantRole = payload.role;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

app.use(extractTenant);

// Search documents endpoint - supports flexible filtering
app.get('/api/documents/search', async (req, res) => {
  const { title, author, date_from, date_to, classification } = req.query;

  let baseQuery = `SELECT id, title, author, classification, created_at 
                   FROM documents WHERE tenant_id = '${req.tenantId}'`;

  // Apply filters
  if (title) {
    baseQuery += ` AND title ILIKE '%${title}%'`;
  }
  if (author) {
    baseQuery += ` AND author = '${author}'`;
  }
  if (date_from) {
    baseQuery += ` AND created_at >= '${date_from}'`;
  }
  if (date_to) {
    baseQuery += ` AND created_at <= '${date_to}'`;
  }
  if (classification) {
    baseQuery += ` AND classification = '${classification}'`;
  }

  baseQuery += ' ORDER BY created_at DESC LIMIT 100';

  try {
    const result = await pool.query(baseQuery);
    return res.json({ documents: result.rows });
  } catch (e) {
    console.error('Query error:', e.message);
    return res.status(500).json({ error: 'Search failed', detail: e.message });
  }
});

// Bulk export endpoint
app.post('/api/documents/export', async (req, res) => {
  const { document_ids, format } = req.body;
  if (!Array.isArray(document_ids) || document_ids.length === 0) {
    return res.status(400).json({ error: 'document_ids required' });
  }

  const idList = document_ids.map(id => `'${id}'`).join(',');
  const query = `SELECT * FROM documents WHERE tenant_id = '${req.tenantId}' AND id IN (${idList})`;

  try {
    const result = await pool.query(query);
    const exportId = crypto.randomUUID();
    // Write to temp export path
    const exportPath = `/tmp/exports/${exportId}.${format || 'json'}`;
    fs.mkdirSync('/tmp/exports', { recursive: true });
    fs.writeFileSync(exportPath, JSON.stringify(result.rows, null, 2));
    return res.json({ export_id: exportId, count: result.rows.length });
  } catch (e) {
    return res.status(500).json({ error: 'Export failed' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(3000, () => console.log('Document service running on :3000'));
